pug:
table.row.footer.iq-footer--footer.iq-footer--bg-col(role="presentation" style="background-color:{{ background_color }};border:{{ border }};border-radius:{{ radius }}")
    tr
        td.pb30
            table.twelve.columns(role="presentation")
                tr
                    td
                        .mobile-paddding.iq-footer--mobile-paddding(style="padding:{{ padding }}")
                            p.iq-footer--warning {{ company_address }}
                            p.iq-footer--warning.pt20 {{ risk_warning }}
                            p.subscribe.iq-footer--subscribe
                                a.left(href="{{ terms_href }}" universal="true" target="_blank") {{ conditions }}
                                a.iq-footer--right(href="{{ unsubscribe_href }}" universal="true" target="_blank") {{ unsubscribe }}

styl:
.iq-footer--footer{background-color:{{ background_color }};border-collapse:separate!important;border-radius:{{ radius }}!important;padding-bottom:0;padding-top:0}
.iq-footer--mobile-paddding{padding:{{ padding }}}
@media screen and (max-width:600px){.iq-footer--mobile-paddding{padding:30px 20px 0!important}}
.iq-footer--warning{color:{{ text_color }};font-family:Helvetica!important;font-size:14px;letter-spacing:0;line-height:22px;text-align:center}
.iq-footer--subscribe{color:{{ link_color }}!important;font-family:'Roboto','Helvetica','Arial',sans-serif;font-size:14px;font-weight:300;margin:0 auto;padding-top:20px;text-align:left!important;text-decoration:none!important}
a.left{color:{{ link_color }};display:inline-block;font-weight:400;text-align:left;word-break:break-word}
a.iq-footer--right{color:{{ link_color }};display:inline-block;float:right;font-weight:400;text-align:right}
@media screen and (max-width:600px){a.left{display:block!important;padding-bottom:10px!important;text-align:center!important}a.iq-footer--right{display:block!important;float:none!important;text-align:center!important}}

/* втянуто из стилей семьи при скоупе — блок больше не зависит от main.styl */
.iq-footer--bg-col{background-color:#f9f9f9}
@media screen and (max-width: 600px){
.iq-footer--right{display:block !important;text-align:center !important;float:none !important}
.iq-footer--right{display:block !important;text-align:center !important;float:none !important;padding-right:0 !important}
.iq-footer--right{display:block !important;float:none !important;text-align:center !important}
}
.iq-footer--right{color:#474a50;display:inline-block;float:right;font-weight:400;text-align:right}
